                <td>\( (0, ah^2+k) \)</td>
            </tr>
            <tr>
                <td>\( y = ax^2 + bx + c \)</td>
                <td>\( \left( -\frac{b}{2a}, \frac{4ac-b^2}{4a} \right) \)</td>
                <td>\( x = -\frac{b}{2a} \)</td>
                <td>\( (0, c) \)</td>
            </tr>
        </table>

